const authKey = env.get('trafikverket_authkey') || global.get('authenticationkey');
const station  = env.get('trafikverket_station')  || global.get('locationSignature');

if (!authKey) {
    node.error('SAKNAR API-NYCKEL: Sätt miljövariabel trafikverket_authkey');
    node.status({ fill: 'red', shape: 'ring', text: 'API-nyckel saknas' });
    return null;
}

if (!station) {
    node.error('SAKNAR STATION: Sätt miljövariabel trafikverket_station');
    node.status({ fill: 'red', shape: 'ring', text: 'Station saknas' });
    return null;
}

global.set('tv_sse_state', 'fetching_url');
global.set('tv_error_count', 0);
global.set('tv_station', station);

const today = new Date().toISOString().split('T')[0];

const xmlQuery =
`<REQUEST>
  <LOGIN authenticationkey="${authKey}" />
  <QUERY objecttype="TrainAnnouncement"
         namespace="rail.trafficinfo"
         schemaversion="2.0"
         sseurl="true">
    <FILTER>
      <AND>
        <EQ name="ActivityType" value="Ankomst" />
        <EQ name="LocationSignature" value="${station}" />
        <EQ name="Advertised" value="true" />
        <GT name="AdvertisedTimeAtLocation" value="${today}T00:00:00" />
        <LT name="AdvertisedTimeAtLocation" value="${today}T23:59:59" />
      </AND>
    </FILTER>
    <INCLUDE>AdvertisedTrainIdent</INCLUDE>
    <INCLUDE>ActivityType</INCLUDE>
    <INCLUDE>LocationSignature</INCLUDE>
    <INCLUDE>AdvertisedTimeAtLocation</INCLUDE>
    <INCLUDE>EstimatedTimeAtLocation</INCLUDE>
    <INCLUDE>EstimatedTimeIsPreliminary</INCLUDE>
    <INCLUDE>TimeAtLocation</INCLUDE>
    <INCLUDE>TrackAtLocation</INCLUDE>
    <INCLUDE>Canceled</INCLUDE>
    <INCLUDE>FromLocation</INCLUDE>
    <INCLUDE>ToLocation</INCLUDE>
    <INCLUDE>ProductInformation</INCLUDE>
    <INCLUDE>TechnicalTrainIdent</INCLUDE>
    <INCLUDE>InformationOwner</INCLUDE>
  </QUERY>
</REQUEST>`;

msg.payload = xmlQuery;
msg.headers = { 'Content-Type': 'text/xml; charset=utf-8' };
msg.method  = 'POST';
msg.url     = 'https://api.trafikinfo.trafikverket.se/v2/data.json';

node.status({ fill: 'blue', shape: 'ring', text: `Hämtar SSE-URL (${station})...` });
return msg;

if (msg.statusCode !== 200) {
    node.error(`HTTP-fel ${msg.statusCode}: ${JSON.stringify(msg.payload)}`);
    node.status({ fill: 'red', shape: 'ring', text: `HTTP ${msg.statusCode} - retry om 30s` });
    return [null, { payload: 'retry' }];
}

try {
    const result = msg.payload?.RESPONSE?.RESULT?.[0];
    if (!result) throw new Error('Tomt RESULT i svar');

    const sseUrl = result?.INFO?.SSEURL;
    if (!sseUrl) throw new Error('Ingen SSEURL i svaret');

    global.set('tv_sse_url', sseUrl);
    global.set('tv_last_event_id', null);
    global.set('tv_sse_state', 'connecting');

    const initialTrains = result?.TrainAnnouncement || [];
    const station = global.get('tv_station') || '?';
    node.log(`SSE-URL OK. ${initialTrains.length} tåg i snapshot för idag (${station}).`);
    node.status({ fill: 'blue', shape: 'dot', text: `SSE-URL OK - ${initialTrains.length} tåg idag` });

    return [{ payload: { url: sseUrl } }, null];

} catch (err) {
    node.error('Parsfel: ' + err.message);
    node.status({ fill: 'red', shape: 'ring', text: 'Parsfel - retry om 30s' });
    return [null, { payload: 'retry' }];
}

const rawData = msg.payload?.data;
if (!rawData) return null;

try {
    const parsed = JSON.parse(rawData);
    const trains = parsed?.RESPONSE?.RESULT?.[0]?.TrainAnnouncement || [];
    if (trains.length === 0) return null;
    return trains.map(train => ({ payload: train, topic: 'train_sse_event' }));
} catch (e) {
    node.warn('SSE JSON-parsfel: ' + e.message);
    return null;
}

global.set('tv_sse_state', 'connected');
global.set('tv_error_count', 0);
const station = global.get('tv_station') || '?';
node.status({ fill: 'green', shape: 'dot', text: `SSE ansluten (${station})` });
node.log('SSE onopen - anslutning etablerad');
return null;

const errorCount = (global.get('tv_error_count') || 0) + 1;
global.set('tv_error_count', errorCount);

const readyState = msg.payload?.readyState;
const statusCode = msg.payload?.status;

node.warn(`SSE-fel #${errorCount} | readyState=${readyState} | HTTP=${statusCode || 'n/a'}`);

if (readyState === 2) {
    node.status({ fill: 'red', shape: 'ring', text: 'SSE dead (state=2) - ny URL om 15s' });
    global.set('tv_sse_state', 'dead');
    global.set('tv_error_count', 0);
    return { payload: 'state2', topic: 'restart' };
}

if (errorCount > 5) {
    node.status({ fill: 'yellow', shape: 'ring', text: `${errorCount} fel - ny URL om 15s` });
    global.set('tv_error_count', 0);
    global.set('tv_sse_state', 'reconnecting');
    return { payload: 'threshold', topic: 'restart' };
}

node.status({ fill: 'yellow', shape: 'ring', text: `SSE-fel #${errorCount} - återansluter...` });
global.set('tv_sse_state', 'reconnecting');
return null;

node.log('Stänger SSE och hämtar ny URL från Trafikverket');
return [
    { payload: 'close' },
    { payload: 'reconnect' }
];

const train = msg.payload;

if (!train || train.ActivityType !== 'Ankomst') return null;

if (train.Canceled === true) {
    node.log(`Tåg ${train.AdvertisedTrainIdent} är inställt - ignoreras`);
    return null;
}

// Trigga endast när tåget faktiskt ankommit (TimeAtLocation satt av Trafikverket)
// Utan detta triggar förseningsnotiser också, vilket är felaktigt
if (!train.TimeAtLocation) {
    node.log(`Tåg ${train.AdvertisedTrainIdent} har inte ankommit (TimeAtLocation saknas) - ignoreras`);
    return null;
}

const dateStr   = new Date().toISOString().split('T')[0];
const dedupeKey = `${train.AdvertisedTrainIdent}_${train.AdvertisedTimeAtLocation}_${dateStr}`;

const seenTrains = global.get('tv_seen_trains') || {};
if (seenTrains[dedupeKey]) {
    node.log(`Tåg ${train.AdvertisedTrainIdent} redan triggat (dedup) - ignoreras`);
    return null;
}

seenTrains[dedupeKey] = { triggeredAt: Date.now(), trainId: train.AdvertisedTrainIdent };
global.set('tv_seen_trains', seenTrains);

const delayed = train.EstimatedTimeAtLocation &&
    train.EstimatedTimeAtLocation !== train.AdvertisedTimeAtLocation;

msg.payload = {
    tag:         train.AdvertisedTrainIdent,
    spar:        train.TrackAtLocation           || 'okänt',
    planerad:    train.AdvertisedTimeAtLocation,
    beraknad:    train.EstimatedTimeAtLocation    || null,
    faktisk:     train.TimeAtLocation,
    forsenat:    delayed,
    fran:        train.FromLocation?.[0]?.LocationName || 'okänt',
    till:        train.ToLocation?.[0]?.LocationName   || 'okänt',
    station:     train.LocationSignature,
    tidsstampel: new Date().toISOString()
};
msg.topic = 'train_arrival';

node.status({
    fill: 'green', shape: 'dot',
    text: `Tåg ${train.AdvertisedTrainIdent} spår ${train.TrackAtLocation || '?'}${delayed ? ' (försenat)' : ''}`
});

return msg;

global.set('tv_seen_trains', {});
global.set('tv_last_event_id', null);
global.set('tv_error_count', 0);
node.log('Midnatt: dedup-cache rensad, hämtar ny SSE-URL för ny dag');
node.status({ fill: 'blue', shape: 'dot', text: 'Midnatt - cache rensad' });
return { payload: 'midnight' };
